select md5(concat_ws('|',incident_type,severity)) incident_type_key, incident_type tipo,
       severity severidad, case when upper(severity) in ('HIGH','CRITICAL','SEVERE') then 'grave' else 'normal' end categoria
from (select distinct incident_type, severity from OLIST_SYNTHETIC_V2.silver.stg_external_carrier__carrier_incidents)

select md5(reconciliation_status) reconciliation_status_key, reconciliation_status estado,
       initcap(replace(reconciliation_status,'_',' ')) descripcion
from (select distinct reconciliation_status from OLIST_SYNTHETIC_V2.silver.stg_finance__financial_reconciliation)

select md5(settlement_status) settlement_status_key, settlement_status estado,
       initcap(replace(settlement_status,'_',' ')) descripcion
from (select distinct settlement_status from OLIST_SYNTHETIC_V2.silver.stg_finance__seller_settlements)

select md5(order_status) order_status_key, order_status estado, initcap(replace(order_status,'_',' ')) descripcion,
       case when order_status in ('delivered','shipped') then 'cumplido' when order_status in ('canceled','unavailable') then 'no_cumplido' else 'proceso' end categoria
from (select distinct order_status from OLIST_SYNTHETIC_V2.silver.stg_olist__orders)
